49	            + ": (java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears() < 18 "
50	            + "? OwnerDto.AgeBandEnum.MINOR "
51	            + ": java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears() < 65 "
52	            + "? OwnerDto.AgeBandEnum.ADULT : OwnerDto.AgeBandEnum.SENIOR))")
53	    OwnerDto toOwnerDto(Owner owner);
