66	     * Returns the owner's canonical region (locality): the REGION segment of the customer code when
67	     * present, otherwise the region derived from the city and postcode, or {@code "UNKNOWN"}.
68	     */
69	    default String locality(Owner owner) {
70	        return owner.getCustomerCode() != null
71	            ? owner.getCustomerCode().substring(0, owner.getCustomerCode().indexOf('-'))
72	            : org.springframework.samples.petclinic.util.LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
