76	     * Computes the owner's membership points: 0 to start, plus 2 when an email address is present,
77	     * plus 1 when the namesake count is 0, plus 2 for a household of 3 or more, and plus 3 for
78	     * tenure of at least one elapsed fiscal year (the fiscal year of today is later than the fiscal
79	     * year of the registration date).
80	     */
81	    default int membershipPoints(Owner owner) {
82	        int points = 0;
83	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
84	            points += 2;
