90	            points += 2;
91	        }
92	        if (owner.getRegistrationDate() != null
93	            && org.springframework.samples.petclinic.util.FiscalYear.elapsed(
94	                owner.getRegistrationDate(), java.time.LocalDate.now()) >= 1) {
95	            points += 3;
